import{_ as A}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as h,c as s,o as e,af as r,b as n,w as a,a as o,G as l,ag as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const _=JSON.parse('{"title":"协议地图","description":"互操作组协议按连接方向分组的选型入口——Agent↔工具用 MCP、Editor↔coding agent 用 ACP、Agent↔用户用 AG-UI、Agent↔Agent 用 A2A；附 ACP 三义消歧与组合决策表。","frontmatter":{"title":"协议地图","description":"互操作组协议按连接方向分组的选型入口——Agent↔工具用 MCP、Editor↔coding agent 用 ACP、Agent↔用户用 AG-UI、Agent↔Agent 用 A2A；附 ACP 三义消歧与组合决策表。","domain":"tech","tags":["tech","action","protocols","map"],"navOrder":70,"topicId":"protocol-map","layer":"7","status":"canonical","nodeType":"pattern","owner":"learn-ai","externalOwners":[],"prerequisites":["tool-execution"],"next":["mcp","a2a","acp-agent-client","ag-ui","a2ui-mcp-apps"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/07-interoperability/index.md","filePath":"zh/tech/07-interoperability/index.md","lastUpdated":1791165915000}'),g={name:"zh/tech/07-interoperability/index.md"};function c(p,t,C,m,P,u){const d=h("Mermaid");return e(),s("div",null,[t[2]||(t[2]=r('<blockquote><p><strong>所在组</strong>：互操作 ｜ <strong>上一组出口</strong>：能把模型输出接入会话与状态 ｜ <strong>本组出口</strong>：面对跨界需求能按连接方向选出协议，并说清不选其余协议的理由 <strong>前置</strong>：<a href="./../05-action/tool-execution.html">工具执行工程</a>、<a href="./../00-map/complexity-ladder.html">复杂度决策阶梯</a> ｜ <strong>下一步</strong>：按地图进入 <a href="./mcp.html">MCP</a>、<a href="./a2a.html">A2A</a>、<a href="./acp-agent-client.html">ACP</a>、<a href="./ag-ui.html">AG-UI</a>、<a href="./a2ui-mcp-apps.html">A2UI 与 MCP Apps</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：互操作组的协议不是竞品，而是<strong>各占一条连接方向</strong>。选型的第一问不是「哪个协议更好」，而是「我要连通的<strong>两边是什么</strong>」：Agent 到工具、编辑器到编码智能体、Agent 到用户界面、还是 Agent 到 Agent。方向定了，候选集通常只剩一个；再用信任域与状态需求确认。</p><h3 id="心智模型-按连接方向分组" tabindex="-1">心智模型：按连接方向分组 <a class="header-anchor" href="#心智模型-按连接方向分组" aria-label="Permalink to &quot;心智模型：按连接方向分组&quot;">​</a></h3>',4)),(e(),n(i,null,{default:a(()=>[l(d,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20USER%5B%22%E7%94%A8%E6%88%B7%20%2F%20%E5%BA%94%E7%94%A8%22%5D%20%3C--%20%22AG-UI%3Cbr%2F%3E(%E4%BA%8B%E4%BB%B6%2F%E7%8A%B6%E6%80%81%2F%E4%B8%AD%E6%96%AD)%22%20--%3E%20AGENT%5B%22%E4%BD%A0%E7%9A%84%20Agent%22%5D%0A%20%20%20%20EDITOR%5B%22Editor%20%2F%20IDE%22%5D%20%3C--%20%22ACP%3Cbr%2F%3E(Agent%20Client%20Protocol)%22%20--%3E%20CAGENT%5B%22coding%20agent%22%5D%0A%20%20%20%20AGENT%20%3C--%20%22MCP%3Cbr%2F%3E(tools%2Fresources%2Fprompts)%22%20--%3E%20TOOLS%5B%22%E5%B7%A5%E5%85%B7%20%2F%20%E6%95%B0%E6%8D%AE%22%5D%0A%20%20%20%20AGENT%20%3C--%20%22Skills%3Cbr%2F%3E(%E7%9F%A5%E8%AF%86%E6%89%93%E5%8C%85%2C%20%E9%9D%9E%E5%8D%8F%E8%AE%AE)%22%20--%3E%20KNOW%5B%22%E5%8F%AF%E5%A4%8D%E7%94%A8%E6%B5%81%E7%A8%8B%E7%9F%A5%E8%AF%86%22%5D%0A%20%20%20%20AGENT2%5B%22%E5%8F%A6%E4%B8%80%E7%BB%84%E7%BB%87%E7%9A%84%20Agent%22%5D%20%3C--%20%22A2A%3Cbr%2F%3E(Card%2FTask%2FArtifact)%22%20--%3E%20AGENT%0A%20%20%20%20AGENT%20%3C--%20%22A2UI%20%2F%20MCP%20Apps%3Cbr%2F%3E(rendered%20UI)%22%20--%3E%20UI%5B%22%E6%B8%B2%E6%9F%93%E7%95%8C%E9%9D%A2%22%5D%0A%20%20%20%20subgraph%20OBS%5B%22%E8%A7%82%E5%AF%9F%E5%8C%BA%EF%BC%88watchlist%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20ARD%5B%22ARD%20%2F%20MCP%20Registry%3Cbr%2F%3Ediscovery%22%5D%0A%20%20%20%20%20%20%20%20COMMERCE%5B%22UCP%20%2F%20AP2%20%2F%20x402%3Cbr%2F%3Ecommerce%22%5D%0A%20%20%20%20end%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=r('<p>注意：<strong>Skills 不是协议</strong>——它是知识打包格式（无 wire 层），画进图里只为占住「可复用知识」这条方向；<a href="./../06-agent-systems/plugins.html">Plugins</a> 同理，占住「能力组合打包」方向。</p><h3 id="协议全景表" tabindex="-1">协议全景表 <a class="header-anchor" href="#协议全景表" aria-label="Permalink to &quot;协议全景表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>连接方向</th><th>协议/格式</th><th>状态</th><th>一句话职责</th><th>详情</th></tr></thead><tbody><tr><td>可复用知识 → Agent</td><td>Agent Skills</td><td>canonical</td><td>指令+资源的打包格式，渐进披露</td><td><a href="./../06-agent-systems/skills.html">Skills</a></td></tr><tr><td>能力组合 → 分发包</td><td>Agent Plugins</td><td>watchlist</td><td>plugin.json 清单 + 固定发现位置</td><td><a href="./../06-agent-systems/plugins.html">Plugins</a></td></tr><tr><td>Agent ↔ 工具/数据</td><td>MCP</td><td>canonical</td><td>JSON-RPC：tools/resources/prompts</td><td><a href="./mcp.html">MCP</a></td></tr><tr><td>Editor/IDE ↔ coding agent</td><td>ACP（Agent Client Protocol）</td><td>canonical</td><td>编辑器与编码智能体的标准通信</td><td><a href="./acp-agent-client.html">ACP</a></td></tr><tr><td>Agent ↔ 用户/应用</td><td>AG-UI</td><td>canonical</td><td>事件流/状态/中断的用户交互协议</td><td><a href="./ag-ui.html">AG-UI</a></td></tr><tr><td>Agent ↔ Agent</td><td>A2A</td><td>canonical</td><td>跨框架 Agent 互操作（Card→Task→Artifact）</td><td><a href="./a2a.html">A2A</a></td></tr><tr><td>Agent ↔ 渲染 UI</td><td>A2UI / MCP Apps</td><td>canonical</td><td>会话内渲染的交互 UI 元素</td><td><a href="./a2ui-mcp-apps.html">A2UI 与 MCP Apps</a></td></tr><tr><td>discovery / registry</td><td>ARD、MCP Registry</td><td>watchlist</td><td>能力与资源发现</td><td><a href="./watchlist.html">协议观察清单</a></td></tr><tr><td>commerce（支付/结算）</td><td>UCP、AP2、x402</td><td>watchlist</td><td>Agent 商务支付轨道</td><td><a href="./watchlist.html">协议观察清单</a></td></tr></tbody></table><h3 id="acp-三义消歧-读任何-acp-资料前先对表" tabindex="-1">ACP 三义消歧（读任何 ACP 资料前先对表） <a class="header-anchor" href="#acp-三义消歧-读任何-acp-资料前先对表" aria-label="Permalink to &quot;ACP 三义消歧（读任何 ACP 资料前先对表）&quot;">​</a></h3><p>「ACP」是重灾区缩写，至少三个不同事物共用：</p><table tabindex="0"><thead><tr><th>#</th><th>全称</th><th>是什么</th><th>边界</th><th>状态</th></tr></thead><tbody><tr><td>①</td><td><strong>Agent Client Protocol</strong>（agentclientprotocol.com）</td><td>编辑器/IDE ↔ coding agent 的标准通信协议；本地走 JSON-RPC over stdio，远程走 HTTP/WebSocket；复用 MCP 的 JSON 表示</td><td>本互操作组协议地图中的 ACP 指<strong>它</strong>；详情见 <a href="./acp-agent-client.html">ACP 章</a></td><td>活跃（Zed 等编辑器生态）</td></tr><tr><td>②</td><td>IBM/BeeAI <strong>Agent Communication Protocol</strong></td><td>历史上的 Agent↔Agent 通信方案</td><td>已并入 A2A 路线；读旧资料遇到时按 A2A 前身理解</td><td>历史</td></tr><tr><td>③</td><td>OpenClaw 内部 <strong>Agent Communication Protocol</strong></td><td>OpenClaw 产品的私有内部协议，与 ①② 无关</td><td>产品实现细节，见 <a href="/zh/products/openclaw/source-code/acp.html">OpenClaw 源码：ACP</a></td><td>产品私有</td></tr></tbody></table><p>引用规则：本互操作组所有页面中未加限定的「ACP」一律指 ①；提 ② 必须带「IBM/BeeAI」前缀并注明历史；提 ③ 必须带「OpenClaw」前缀并链到产品区。</p><h3 id="选择决策表" tabindex="-1">选择决策表 <a class="header-anchor" href="#选择决策表" aria-label="Permalink to &quot;选择决策表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>需求</th><th>方向</th><th>信任域</th><th>状态需求</th><th>最低复杂度选择</th></tr></thead><tbody><tr><td>让 Agent 调用工具/读数据</td><td>Agent → 工具</td><td>工具边界</td><td>server 进程/无状态请求</td><td>MCP</td></tr><tr><td>编辑器接入编码智能体</td><td>Editor ↔ agent</td><td>本机进程或远程</td><td>会话/流式 diff</td><td>ACP①</td></tr><tr><td>前端应用承接 Agent 过程</td><td>Agent → 用户 UI</td><td>应用边界</td><td>事件流/中断</td><td>AG-UI</td></tr><tr><td>两个独立 Agent 协作</td><td>Agent ↔ Agent</td><td>跨组织/跨框架</td><td>异步 Task/Artifact</td><td>A2A</td></tr><tr><td>Agent 输出可交互 UI</td><td>Agent → 渲染 UI</td><td>host 渲染边界</td><td>UI payload</td><td>A2UI / MCP Apps</td></tr><tr><td>只是复用一段流程知识</td><td>知识 → 上下文</td><td>宿主进程内</td><td>无</td><td>Skills（非协议）</td></tr><tr><td>同 host 内一个函数</td><td>进程内</td><td>进程内</td><td>无</td><td>直接函数调用（别上协议）</td></tr></tbody></table><p>最后一行是防御性提醒：协议解决<strong>跨边界</strong>的通信与发现；同进程内的调用用函数即可，<a href="./../00-map/complexity-ladder.html">复杂度决策阶梯</a>的梯级 6 触发条件未命中时不要引入任何本页协议。</p><h3 id="组合示例-一次真实协作的协议拼图" tabindex="-1">组合示例：一次真实协作的协议拼图 <a class="header-anchor" href="#组合示例-一次真实协作的协议拼图" aria-label="Permalink to &quot;组合示例：一次真实协作的协议拼图&quot;">​</a></h3>',11)),(e(),n(i,null,{default:a(()=>[l(d,{id:"mermaid-431",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20U%5B%22%E7%94%A8%E6%88%B7%22%5D%20--%20%22AG-UI%20%E4%BA%8B%E4%BB%B6%E6%B5%81%22%20--%3E%20A%5B%22%E6%9C%AC%E5%9C%B0%20Agent%22%5D%0A%20%20%20%20A%20--%20%22MCP%22%20--%3E%20T%5B%22%E5%B7%A5%E5%85%B7%2F%E6%95%B0%E6%8D%AE%20server%22%5D%0A%20%20%20%20A%20--%20%22A2A%22%20--%3E%20B%5B%22%E5%8F%A6%E4%B8%80%E7%BB%84%E7%BB%87%E7%9A%84%20Agent%22%5D%0A%20%20%20%20A%20--%20%22A2UI%2FMCP%20Apps%22%20--%3E%20R%5B%22%E4%BC%9A%E8%AF%9D%E5%86%85%E6%B8%B2%E6%9F%93%20UI%22%5D%0A%20%20%20%20A%20--%20%22Skills%22%20--%3E%20K%5B%22%E6%B5%81%E7%A8%8B%E7%9F%A5%E8%AF%86%E5%8C%85%22%5D%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[o(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=r('<p>一次会话可以同时用到四条方向：AG-UI 承接用户侧的过程展示，MCP 接工具，A2A 把子任务委托给远端 Agent，Skills 决定「按什么步骤做」。协议之间互补，不存在「全家用一个协议」的合理架构。</p><h3 id="何时使用-何时不用" tabindex="-1">何时使用 / 何时不用 <a class="header-anchor" href="#何时使用-何时不用" aria-label="Permalink to &quot;何时使用 / 何时不用&quot;">​</a></h3><ul><li>用：任何跨进程/跨组织/跨信任域的连通选型；评审「要不要引入协议 X」。</li><li>不用：协议内部的消息结构学习——进入对应详情页。</li></ul><p>历史版本里程碑：本地图于 2026-09 随 Issue #116 冻结；各协议自身版本（如 MCP 2026-07-28、A2A 1.0.0、ACP v1 稳定 + v2 Draft、Agent Plugins 1.0.0）在各自详情页维护（2026-09-01 复核：MCP 与 A2A 无版本漂移，ACP 出现 v2 Draft，见其详情页）。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><p>本页是选型地图，无可运行代码产物；「使用」= 决策演练（纸面即可，≤15 分钟）。验收标准：四个场景全部选中唯一协议并说出不选其余的理由。</p><h3 id="演练-四个场景" tabindex="-1">演练：四个场景 <a class="header-anchor" href="#演练-四个场景" aria-label="Permalink to &quot;演练：四个场景&quot;">​</a></h3><p><strong>场景 A</strong>：VS Code 里换一个新出的编码智能体，希望不写集成代码。</p><ul><li>预期：ACP①。连接方向是 Editor ↔ coding agent。</li><li>反例判断：不是 MCP（那是 Agent ↔ 工具）；不是 A2A（两端不是两个自治 Agent）。</li></ul><p><strong>场景 B</strong>：让自家 Agent 读写公司 wiki 与工单系统。</p><ul><li>预期：MCP。方向是 Agent ↔ 工具/数据。</li><li>反例判断：若 wiki 只需要「按什么步骤查」，那是 Skills；连接与流程是两条方向。</li></ul><p><strong>场景 C</strong>：两个部门各自的 Agent（不同框架）要互派长任务。</p><ul><li>预期：A2A。方向是 Agent ↔ Agent，跨团队信任域，任务异步。</li><li>反例判断：若是同一运行时内的子任务委派，用运行时自带的 subagent 机制，不需要 A2A。</li></ul><p><strong>场景 D</strong>：Agent 分析过程要实时显示在自家 React 应用里，可打断。</p><ul><li>预期：AG-UI。方向是 Agent → 用户界面的事件流。</li><li>反例判断：若只是「在聊天里渲染一张图表」，那是 A2UI / MCP Apps 的 host 渲染，不是应用级事件流。</li></ul><h3 id="使用边界" tabindex="-1">使用边界 <a class="header-anchor" href="#使用边界" aria-label="Permalink to &quot;使用边界&quot;">​</a></h3><ul><li>本地图判断<strong>选哪个方向</strong>；每个协议的版本、消息与安全在详情页。</li><li>观察区（watchlist）协议不进决策表：没有生产证据前，只记录不推荐。</li></ul><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><h3 id="为什么按「连接方向」而不是「功能强弱」组织" tabindex="-1">为什么按「连接方向」而不是「功能强弱」组织 <a class="header-anchor" href="#为什么按「连接方向」而不是「功能强弱」组织" aria-label="Permalink to &quot;为什么按「连接方向」而不是「功能强弱」组织&quot;">​</a></h3><p>协议的成本来自<strong>边界</strong>而非功能：每引入一条协议边界，就多一套版本协商、授权与失败语义。连接方向是边界的自然坐标——两边的身份（用户/编辑器/Agent/工具）决定了谁发起、谁渲染、谁付费、谁担责。功能强弱的对比（谁的消息更丰富）在没有方向约束时没有意义：AG-UI 的事件流再丰富也不能替代 MCP 的工具授权。</p><h3 id="mcp-与-a2a-互补不竞争-官方口径" tabindex="-1">MCP 与 A2A 互补不竞争（官方口径） <a class="header-anchor" href="#mcp-与-a2a-互补不竞争-官方口径" aria-label="Permalink to &quot;MCP 与 A2A 互补不竞争（官方口径）&quot;">​</a></h3><p>A2A 官方文档明确表述：「MCP 与 A2A 不是竞争者，而是高度互补」——<strong>MCP 管 Agent↔工具</strong>（连接 API 与资源），<strong>A2A 管 Agent↔Agent</strong>（发现、委托、共享结果）。选型冲突时不需要在两者间二选一（retrievedAt 2026-09-01）。</p><h3 id="观察区的准入规则" tabindex="-1">观察区的准入规则 <a class="header-anchor" href="#观察区的准入规则" aria-label="Permalink to &quot;观察区的准入规则&quot;">​</a></h3><p>一条协议进入 watchlist 只需「有官方规范或活跃维护者」；升入 canonical 决策表需要：learn-ai 或 sibling 有真实消费证据，或生态出现多个独立实现。ARD、MCP Registry、UCP、AP2、x402 等当前全部停留在观察区，详情与核验日期见<a href="./watchlist.html">协议观察清单</a>。</p><h3 id="规范要求-vs-本地实测" tabindex="-1">规范要求 vs 本地实测 <a class="header-anchor" href="#规范要求-vs-本地实测" aria-label="Permalink to &quot;规范要求 vs 本地实测&quot;">​</a></h3><p>本页是选型模式，无规范可实现测；「规范 vs 实测」分栏在四个 canonical 协议详情页各自维护（<a href="./mcp.html">MCP</a>、<a href="./a2a.html">A2A</a>、<a href="./acp-agent-client.html">ACP</a>、<a href="./ag-ui.html">AG-UI</a>）。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p>本页无代码集成；「开发」= 把地图用作架构评审的门禁。</p><h3 id="症状-→-证据-→-处理-→-完成标准" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：评审争论「用 MCP 还是 A2A」，双方各列功能清单。 <strong>证据</strong>：没人先陈述连接方向——两端身份（Agent↔工具 还是 Agent↔Agent）未被定义。 <strong>处理</strong>：先填选择决策表的「方向/信任域/状态」三列；候选集会收敛到一个。 <strong>完成标准</strong>：设计文档写明两端身份与方向，选型结论直接由表格导出。</p><h3 id="症状-→-证据-→-处理-→-完成标准-1" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-1" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：文档/方案里的「ACP」读者理解不一致，讨论串楼层越来越歪。 <strong>证据</strong>：没有限定词——可能是 Agent Client Protocol、IBM 历史 ACP 或 OpenClaw 私有 ACP。 <strong>处理</strong>：按三义消歧表补限定词；站内默认 ①，其余必须带前缀。 <strong>完成标准</strong>：该文档中每个 ACP 出现处都能唯一对应表中一行。</p><h3 id="症状-→-证据-→-处理-→-完成标准-2" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-2" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：方案引用了 watchlist 协议（如 x402）作为关键路径依赖。 <strong>证据</strong>：该协议无本站消费证据，决策表未收录。 <strong>处理</strong>：降级为「观察项」：主路径改用 canonical 协议或显式自定义层，watchlist 协议列为可选实验。 <strong>完成标准</strong>：关键路径不依赖任何 watchlist 条目；实验项有独立开关与回退。</p><h3 id="反模式清单" tabindex="-1">反模式清单 <a class="header-anchor" href="#反模式清单" aria-label="Permalink to &quot;反模式清单&quot;">​</a></h3><ul><li><strong>方向未定先选协议</strong>：拿功能清单代替连接方向分析。</li><li><strong>一词三义</strong>：不加限定地使用 ACP。</li><li><strong>把观察区当货架</strong>：在关键路径采用无生产证据的新协议。</li></ul><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>四级阅读路线：</p><ul><li><strong>Beginner</strong>：读本页，能复述全景表与三义消歧。</li><li><strong>Builder</strong>：进 <a href="./mcp.html">MCP</a> 跑通零依赖 server+client fixture；再按方向读 ACP/AG-UI。</li><li><strong>Operator</strong>：把选择决策表用作评审模板；跟踪各协议版本公告。</li><li><strong>Researcher</strong>：读 A2A 官网「How A2A Works with MCP」与各规范原文，验证互补口径。</li></ul><h3 id="资源表" tabindex="-1">资源表 <a class="header-anchor" href="#资源表" aria-label="Permalink to &quot;资源表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>证据层级</th><th>canonical URL</th><th>用途</th><th>支持的断言</th><th>下一步</th></tr></thead><tbody><tr><td>A2A 官网（含 MCP 互补口径）</td><td>L0（官方）</td><td><a href="https://a2a-protocol.org/latest/" target="_blank" rel="noreferrer">https://a2a-protocol.org/latest/</a></td><td>A2A 与 MCP 分工的官方表述</td><td>「MCP↔工具、A2A↔Agent，互补不竞争」（retrievedAt 2026-09-01）</td><td><a href="./a2a.html">A2A</a></td></tr><tr><td>Agent Client Protocol 官网</td><td>L0（官方）</td><td><a href="https://agentclientprotocol.com/" target="_blank" rel="noreferrer">https://agentclientprotocol.com/</a></td><td>ACP① 的定义</td><td>「标准化 code editors/IDEs 与 coding agents 的通信」（retrievedAt 2026-09-01）</td><td><a href="./acp-agent-client.html">ACP</a></td></tr><tr><td>MCP 规范</td><td>L0（官方规范）</td><td><a href="https://modelcontextprotocol.io/specification/latest" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/latest</a></td><td>Agent↔工具方向的规范</td><td>协议职责与版本（retrievedAt 2026-09-01）</td><td><a href="./mcp.html">MCP</a></td></tr><tr><td>AG-UI 文档</td><td>L0（官方）</td><td><a href="https://docs.ag-ui.com/introduction" target="_blank" rel="noreferrer">https://docs.ag-ui.com/introduction</a></td><td>Agent↔用户方向的规范</td><td>事件/状态/中断模型（retrievedAt 2026-09-01，详情页复核）</td><td><a href="./ag-ui.html">AG-UI</a></td></tr></tbody></table><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>证伪入口：若你遇到一个真实需求，按选择决策表会落到两个协议（或零个），说明地图的方向坐标不完备——修订本表而不是掩盖场景。</li><li>未决：观察区协议（ARD/Registry/UCP/AP2/x402）的升格评审在<a href="./watchlist.html">协议观察清单</a>持续进行；A2UI 与 MCP Apps 的边界分工在<a href="./a2ui-mcp-apps.html">其详情页</a>维护。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>四个 canonical 协议的原理与 fixture：<a href="./mcp.html">MCP</a>、<a href="./a2a.html">A2A</a>、<a href="./acp-agent-client.html">ACP</a>、<a href="./ag-ui.html">AG-UI</a>。</li><li>选型之前的总纲：<a href="./../00-map/complexity-ladder.html">复杂度决策阶梯</a>——梯级 6 未触发就不需要本页任何协议。</li></ul>',45))])}const x=A(g,[["render",c]]);export{_ as __pageData,x as default};
